-- Update Cristiano Ronaldo/Messi/Neymar natural positions and CR7 attached face.
-- The CR7 image_url uses a compact data URL derived from the user-provided attachment in this chat.

with cr7_face(image_url) as (
  values ($cr7_face$data:image/jpeg;base64,$cr7_face$)
), cr7_updates as (
  select c.id,
    case
      when c.id = 'cristiano-ronaldo-2014-special' then 94
      when c.id = 'cristiano-ronaldo-2017-special' then 98
      when c.id = 'icon_cristiano_ronaldo_2017' then 98
      else c.overall
    end as overall
  from public.fa_catalog_players c
  where c.enabled
    and lower(c.name) like '%cristiano ronaldo%'
)
update public.fa_catalog_players c
set image_url = f.image_url,
    image_source_url = 'user_attachment:1790160611623.jpeg',
    image_license = 'user-provided image for Football Auction',
    primary_position = case
      when c.id = 'cristiano-ronaldo-2008-special' then 'PD'
      when c.id = 'cristiano-ronaldo-2014-special' then 'PE'
      else 'ATA'
    end,
    secondary_positions = case
      when c.id = 'cristiano-ronaldo-2008-special' then array['ATA','PE']::text[]
      when c.id = 'cristiano-ronaldo-2014-special' then array['ATA','PD']::text[]
      else array['PD','PE']::text[]
    end,
    overall = u.overall,
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object(
      'image_source', 'user_provided_attachment',
      'image_file', '1790160611623.jpeg',
      'image_checked_at', '2026-09-23',
      'natural_positions', array['ATA','PD','PE'],
      'position_penalty_note', 'ATA, PD and PE are natural positions for this Football Auction card.',
      'rating_source', 'Football Auction game design',
      'rating_status', 'custom_game_design',
      'not_official_ea_fc27', true
    )
from cr7_updates u
cross join cr7_face f
where c.id = u.id;

update public.fa_catalog_players c
set primary_position = case
      when c.id in ('ea27_lionel_messi', 'lionel-messi-2012-special', 'lionel-messi-2014-special') then 'ATA'
      else c.primary_position
    end,
    secondary_positions = case
      when c.id in ('ea27_lionel_messi', 'lionel-messi-2012-special', 'lionel-messi-2014-special') then array['PD','PE']::text[]
      when c.id in ('lionel-messi-2009-special', 'lionel-messi-2015-special') then array['ATA','PE']::text[]
      else array['ATA','PD','PE']::text[]
    end,
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object(
      'natural_positions', array['ATA','PD','PE'],
      'position_penalty_note', 'ATA, PD and PE are natural positions for this Football Auction card.'
    )
where c.enabled and c.name = 'Lionel Messi';

update public.fa_catalog_players c
set primary_position = case
      when c.id in ('neymar-2020-special') then 'MEI'
      else 'PE'
    end,
    secondary_positions = case
      when c.id in ('neymar-2020-special') then array['PE','PD']::text[]
      else array['PD','MEI']::text[]
    end,
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object(
      'natural_positions', array['PE','PD','MEI'],
      'position_penalty_note', 'PE, PD and MEI are natural positions for this Football Auction card.'
    )
where c.enabled and c.name in ('Neymar', 'Neymar Jr.');

update public.fa_players p
set image_url = c.image_url,
    primary_position = c.primary_position,
    secondary_positions = c.secondary_positions,
    overall = c.overall,
    metadata = coalesce(p.metadata, '{}'::jsonb) || jsonb_build_object(
      'catalog_id', c.id,
      'natural_positions', c.metadata->'natural_positions',
      'catalog_sync', '2026-09-23_cr7_face_positions'
    )
from public.fa_catalog_players c
where p.catalog_id = c.id
  and c.enabled
  and (
    lower(c.name) like '%cristiano ronaldo%'
    or c.name = 'Lionel Messi'
    or c.name in ('Neymar', 'Neymar Jr.')
  );

create or replace function private.fa_x1_player_penalty(primary_position text, secondary_positions text[], slot text, mode text)
returns integer
language sql
immutable
set search_path to ''
as $function$
  select min(private.fa_x1_penalty(pos, slot, mode))
  from unnest(array_append(coalesce(secondary_positions, array[]::text[]), primary_position)) as positions(pos)
  where pos is not null and btrim(pos) <> '';
$function$;

create or replace function private.fa_x1_snapshot(p_member uuid)
returns jsonb
language sql
stable
set search_path to ''
as $function$
 select jsonb_build_object('id',m.id,'name',m.display_name,'players',coalesce((
  select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name||case when p.player_type='SPECIAL' then ' '||coalesce(p.metadata->>'version_label','') else '' end,
   'slot',s.slot_key,'overall',p.overall,'penalty',coalesce(private.fa_x1_player_penalty(p.primary_position,p.secondary_positions,s.slot_key,r.mode),4)) order by s.slot_key collate "C")
  from public.fa_squad_players s join public.fa_players p on p.id=s.player_id where s.member_id=m.id),'[]'::jsonb))
 from public.fa_room_members m join public.fa_rooms r on r.id=m.room_id where m.id=p_member;
$function$;
